a and all work built specifically for the customer.\",\"question_for_counsel\":\"Confirm customer ownership of data and bespoke deliverables.\",\"verbatim_key_sentence\":\"The supplier owns all customer data and all work built specifically for the customer.\"},{\"clause_id\":\"C4\",\"heading\":\"Payment\",\"topic\":\"payment\",\"position\":\"matches_playbook\",\"severity\":\"none\",\"breaches_hard_limit\":false,\"which_hard_limit\":\"\",\"explanation\":\"The synthetic clause matches the corresponding playbook position.\",\"business_impact\":\"\",\"suggested_redline\":\"\",\"question_for_counsel\":\"\",\"verbatim_key_sentence\":\"Correct invoices are payable net thirty days and annual price increases are capped at five percent.\"},{\"clause_id\":\"C5\",\"heading\":\"Confidentiality\",\"topic\":\"confidentiality\",\"position\":\"matches_playbook\",\"severity\":\"none\",\"breaches_hard_limit\":false,\"which_hard_limit\":\"\",\"explanation\":\"The synthetic clause matches the corresponding playbook position.\",\"business_impact\":\"\",\"suggested_redline\":\"\",\"question_for_counsel\":\"\",\"verbatim_key_sentence\":\"Mutual confidentiality obligations survive termination for three years.\"}]}]");
const collate = $('Collate Clause Findings');
const items = collate.isExecuted ? collate.all(0, 0) : [];
const actual = items.map(item => item.json);
const summary = actual[0];
const evidence = {
  clause_ids: (summary?.findings || []).map(f => f.clause_id),
  clauses_assessed: summary?.clauses_assessed,
  blocker_ids: (summary?.findings || []).filter(f => f.severity === 'blocker').map(f => f.clause_id),
  hard_limit_ids: (summary?.findings || []).filter(f => f.breaches_hard_limit).map(f => f.clause_id),
  verdict: summary?.verdict,
};
if (!equalJson(actual, expected)) throw new Error(
  'SEVENEDGE five-clause release regression: expected IDs C1,C2,C3,C4,C5; blocker C3; hard-limit C3; DO_NOT_SIGN. Actual ' + JSON.stringify(evidence));
return [{ json: { status: 'passed', fixture: 'SEVENEDGE five-clause pure-JSON loop', ...evidence, summary } }];
